{"path":".suffice-v10-checks/long-build-range.cjs","content":"'use strict'
const test = require('node:test')
const assert = require('node:assert/strict')
const { Range } = require('../src/index.js')

test('loose range keeps trailing build metadata out of the patch number', () => {
  const range = new Range('4.17.0+' + 'a'.repeat(250) + '3', { loose: true })
  assert.equal(range.range, '4.17.0')
  assert.equal(range.test('4.17.0'), true)
  assert.equal(range.test('4.17.3'), false)
  assert.equal(range.test('4.17.1'), false)
  assert.equal(range.test('4.16.9'), false)
})
