{"path":".suffice-v10-checks/final-failure.test.mjs","content":"import test from 'node:test';
import assert from 'node:assert/strict';
import { retry } from '../src/retry.mjs';

test('final failure preserves identity without consulting predicate or sleeping', async () => {
  const failure = new Error('operation failed');
  const attempts = [];
  let predicateCalls = 0;
  let sleepCalls = 0;

  await assert.rejects(
    retry(async (attempt) => {
      attempts.push(attempt);
      throw failure;
    }, {
      attempts: 1,
      shouldRetry() {
        predicateCalls += 1;
        return true;
      },
      async sleep() {
        sleepCalls += 1;
      },
    }),
    (error) => error === failure,
  );

  assert.deepEqual(attempts, [1]);
  assert.equal(predicateCalls, 0);
  assert.equal(sleepCalls, 0);
});
","command":["node","--test",".suffice-v10-checks/final-failure.test.mjs"],"requirementQuote":"Pass a one-based attempt number to operation. Resolve immediately on success. On rejection, preserve the exact error identity; consult shouldRetry(error, attempt) only when another attempt remains. A false predicate stops retries. Between retryable failures call await sleep(baseDelayMs * 2 ** (attempt - 1)); never sleep after success or the final failure."}

{"path":".suffice-v10-checks/split-utf8.test.mjs","content":"import test from 'node:test';
import assert from 'node:assert/strict';
import { parseJsonLines } from '../src/json-lines.mjs';

test('decodes UTF-8 characters split across byte chunks', async () => {
  const bytes = new TextEncoder().encode('{"text":"€😀"}\n');
  // Every multibyte character is necessarily split across chunks.
  const chunks = Array.from(bytes, byte => Uint8Array.of(byte));
  const values = [];
  for await (const value of parseJsonLines(chunks)) values.push(value);
  assert.deepStrictEqual(values, [{ text: '€😀' }]);
});
","command":["node","--test",".suffice-v10-checks/split-utf8.test.mjs"],"requirementQuote":"Accept sync or async iterables of strings or Uint8Array chunks. Parse newline-delimited JSON across arbitrary chunk boundaries, including UTF-8 multibyte characters split across byte chunks."}

